1	#!/usr/bin/env node
2	// readiness.mjs — the requirements readiness review: no card is cut while a decision is missing.
3	//
4	// readiness.json (written from the Business Analyst's READINESS answer) is
5	//   { "items": [ { "id": "ARC-style", "status": "decided" | "n_a" | "open", "answer": "…", "source": "…",
6	//                  "question": "…", "options": ["…"], "impact": "…" } … ],
7	//     "architecture": { "style": "microservices", "components": [
8	//        { "id": "orders-svc", "kind": "service", "stack": ["java","spring-boot"], "path": "services/orders/",
9	//          "owner": "backend", "reviewer": "reviewer-java", "notes": "…" } … ] } }
10	// architecture is the frozen technical frame: every card belongs to one component; its stack decides the dev's
11	// skills and the reviewer. Once the job is planned, readiness.json is frozen (dl checks its hash on every step).
12	//   decided → answer + source (a section of the request, a repo file, or "human: <name> <date>"); a decision taken from
13	//             the request or a repo file also carries `quote`: the words that state it, verbatim ("a … b" for fragments)
14	//   n_a     → answer says why it does not apply + source
15	//   open    → a question (+ options, impact) and its owner:
16	//             "business" — the answer changes scope, observable behaviour, a contract or a business rule → the human answers
17	//             "pm"       — an implementation detail with none of those effects → Michael (the PM) decides, with a rationale
18	// Every catalog item that applies to the job must be present; the BA may add items with ids starting "X-".
19	//
20	//   node readiness.mjs applicable <job dir>              the catalog items that apply (JSON) — given to the BA
21	//   node readiness.mjs check <job dir>                   validate; writes readiness.md and QUESTIONS.md
22	//                                                        exit 0 ready · 1 invalid · 3 open questions remain
23	//   node readiness.mjs clarify <job dir> <id> <by> "<answer>"   record the human's answer
24	import { readFileSync, writeFileSync, existsSync } from "node:fs";
25	import { join, dirname } from "node:path";
26	import { fileURLToPath, pathToFileURL } from "node:url";
27	import { parseYaml, loadCatalog } from "./roles.mjs";
28	
29	const SKILL_DIR = join(dirname(fileURLToPath(import.meta.url)), "..");
30	export const catalog = () => parseYaml(readFileSync(join(SKILL_DIR, "readiness.yaml"), "utf8"), "readiness.yaml").items ?? [];
31	
32	export function areasOf(job) {
33	  const roles = new Set((job.roles ?? []).map((r) => r.role));
34	  const a = new Set(["always", ...(job.areas ?? [])]);
35	  const has = (...xs) => xs.some((x) => roles.has(x));
36	  if (has("backend", "backend-lead", "tech-lead")) a.add("backend").add("data").add("integration");
37	  if (has("frontend", "frontend-lead")) a.add("frontend").add("ui");
38	  if (has("mobile", "mobile-lead", "qa-mobile")) a.add("mobile").add("ui");
39	  return a;
40	}
41	export const applicable = (job) => catalog().filter((i) => areasOf(job).has(i.area));
42	
43	export const KINDS = ["service", "bff", "app", "web", "mobile", "library", "worker", "db", "infra", "docs"];
44	export function readReadiness(jobDir) {
45	  const raw = JSON.parse(readFileSync(join(jobDir, "readiness.json"), "utf8"));
46	  return Array.isArray(raw) ? { items: raw, architecture: null } : { items: raw.items ?? [], architecture: raw.architecture ?? null };
47	}
48	export function checkArchitecture(job, arch) {
49	  const errors = [];
50	  if (!arch) return ["architecture is missing — the BA's READINESS answer lists every component (ARC-components)"];
51	  const comps = arch.components;
52	  if (!arch.style) errors.push("architecture.style is missing (monolith | modular-monolith | microservices | library | …)");
53	  if (!Array.isArray(comps) || !comps.length) return [...errors, "architecture.components must list at least one component"];
54	  const cat = loadCatalog(), roles = new Map((job.roles ?? []).map((r) => [r.role, r]));
55	  const ids = new Set();
56	  for (const c of comps) {
57	    const id = c.id ?? "(no id)";
58	    if (!/^[a-z0-9][a-z0-9-]*$/.test(id)) errors.push(`component '${id}': id must be lower-case kebab-case`);
59	    if (ids.has(id)) errors.push(`component '${id}': duplicate id`); ids.add(id);
60	    if (!KINDS.includes(c.kind)) errors.push(`component '${id}': kind must be one of ${KINDS.join(", ")}`);
61	    if (!Array.isArray(c.stack) || !c.stack.length) errors.push(`component '${id}': stack must list its languages/frameworks (e.g. ["java","spring-boot"])`);
62	    const ps = Array.isArray(c.path) ? c.path : [c.path];
63	    if (!ps.length || ps.some((x) => typeof x !== "string" || !x || x.startsWith("/") || x.split("/").includes("..")))
64	      errors.push(`component '${id}': path must be a repo-relative directory or file, or a list of them, e.g. ["src/orders/", "test/orders/"] ("." for the root); a card's scope must lie inside these`);
65	    const owner = roles.get(c.owner);
66	    if (!owner) errors.push(`component '${id}': owner '${c.owner}' is not a role on this job`);
67	    else if (cat.roles?.[c.owner]?.kind !== "dev") errors.push(`component '${id}': owner '${c.owner}' must be a dev role`);
68	    const want = (c.stack ?? []).map((st) => cat.stack_reviewers?.[st]).filter(Boolean);
69	    const rev = roles.get(c.reviewer);
70	    if (!c.reviewer || !rev || !String(c.reviewer).startsWith("reviewer")) errors.push(`component '${id}': reviewer must name a reviewer role on this job (e.g. "reviewer-${(c.stack ?? ["x"])[0]}")`);
71	    else if (want.length && !want.includes(rev.agent)) errors.push(`component '${id}': reviewer ${c.reviewer} (${rev.agent}) does not match its stack — use one of ${[...new Set(want)].join(", ")}`);
72	  }
73	  return errors;
74	}
75	
76	// A decision is only as good as its source: one taken from the request (or a repo file) must quote the words that state
77	// it. An interpretation of a term the request uses but does not define is not a decision — it is an open business item.
78	// (Seen live: "Input is trimmed" was decided as String.prototype.trim(), citing a clause that never defined trimming.)
79	const norm = (t) => String(t).toLowerCase().replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/\s+/g, " ").trim();
80	function quoteError(i, job) {
81	  const src = String(i.source);
82	  if (/^\s*(human|pm):/i.test(src)) return null;                 // answered by the business / decided by Michael (dl clarify / dl decide)
83	  if (!i.quote || !String(i.quote).trim()) return 'decided from a source needs `quote`: the words of the request (or repo file) that state this decision, verbatim. If the source only uses the term without stating the decision, the item is open (owner "business")';
84	  let hay = norm(job.request ?? "");
85	  for (const m of src.matchAll(/[\w./-]+\.(md|json|ya?ml|txt|mjs|js|ts|java|go|py|kt|swift)\b/g)) {
86	    try { hay += " " + norm(readFileSync(join(job.repo ?? ".", m[0]), "utf8")); } catch { /* not a repo file (e.g. the request's own name) */ }
87	  }
88	  const miss = String(i.quote).split(/\s*(?:…|\.\.\.)\s*/).map(norm).filter(Boolean).filter((f) => !hay.includes(f));
89	  return miss.length ? `quote not found in the request${/\.\w+\b/.test(src) ? " or the named file" : ""}: "${miss[0].slice(0, 80)}" — quote the exact words, or make the item open` : null;
90	}
91	
92	export function check(jobDir) {
93	  const job = JSON.parse(readFileSync(join(jobDir, "job.json"), "utf8"));
94	  const file = join(jobDir, "readiness.json");
95	  const errors = [];
96	  if (!existsSync(file)) return { errors: ["readiness.json is missing — the Business Analyst's READINESS review writes it"], open: [], items: [] };
97	  let items, architecture;
98	  try { ({ items, architecture } = readReadiness(jobDir)); } catch (e) { return { errors: [`readiness.json: ${e.message}`], open: [], items: [] }; }
99	  if (!Array.isArray(items)) return { errors: ["readiness.json: items must be an array"], open: [], items: [] };
100	  const byId = new Map(items.map((i) => [i.id, i]));
101	  for (const c of applicable(job)) if (!byId.has(c.id)) errors.push(`${c.id} (${c.q}) is not answered`);
102	  const known = new Set(catalog().map((c) => c.id));
103	  for (const i of items) {
104	    if (!i.id) { errors.push("an item has no id"); continue; }
105	    if (!known.has(i.id) && !String(i.id).startsWith("X-")) errors.push(`${i.id}: unknown id (extra items start with "X-")`);
106	    if (!["decided", "n_a", "open"].includes(i.status)) errors.push(`${i.id}: status must be decided | n_a | open`);
107	    if (i.status === "decided" && (!i.answer || !i.source)) errors.push(`${i.id}: decided needs an answer and its source`);
108	    if (i.status === "decided" && i.source) { const e = quoteError(i, job); if (e) errors.push(`${i.id}: ${e}`); }
109	    if (i.status === "n_a" && (!i.answer || !i.source)) errors.push(`${i.id}: n_a needs the reason (answer) and its source`);
110	    if (i.status === "open" && !i.question) errors.push(`${i.id}: open needs a question`);
111	    if (i.status === "open" && !["business", "pm"].includes(i.owner)) errors.push(`${i.id}: open needs owner "business" (scope/behaviour/contract/business rule) or "pm" (implementation detail)`);
112	  }
113	  errors.push(...checkArchitecture(job, architecture).map((e) => `architecture: ${e}`));
114	  // A decided item that needs a specialist brings that ECC role onto the job (e.g. an a11y target → ecc:a11y-architect).
115	  const onJob = new Set((job.roles ?? []).map((r) => r.role)), cat = catalog();
116	  const warnings = [];
117	  for (const i of items) {
118	    const c = cat.find((x) => x.id === i.id);
119	    if (i.status !== "decided" || !c) continue;
120	    if (c.requires_role && !onJob.has(c.requires_role)) errors.push(`${i.id} is decided ("${String(i.answer).slice(0, 60)}") → role '${c.requires_role}' must be on the job (dl jobset, see roles.yaml)`);
121	    if (c.suggests_role && !onJob.has(c.suggests_role)) warnings.push(`${i.id} is decided → consider role '${c.suggests_role}' (its 'when' rule in roles.yaml decides)`);
122	  }
123	  const open = items.filter((i) => i.status === "open");
124	  const openBusiness = open.filter((i) => i.owner !== "pm"), openPm = open.filter((i) => i.owner === "pm");
125	  const q = (c) => catalog().find((x) => x.id === c.id)?.q ?? c.question ?? "";
126	  const md = [`# Readiness — ${job.id}`, "", `${items.length} item(s): ${items.filter((i) => i.status === "decided").length} decided · ` +
127	    `${items.filter((i) => i.status === "n_a").length} not applicable · ${open.length} open`, "",
